-- ============================================================
-- CampusConnect: Real dataset seed (generated from Placement.csv)
-- 1000 students derived from actual CGPA / Internships / Placed /
-- Salary values in the uploaded dataset. Run on a FRESH database
-- (see instructions) since this script assigns explicit IDs.
-- ============================================================
USE campusconnect;

SET FOREIGN_KEY_CHECKS=0;
TRUNCATE TABLE applications;
TRUNCATE TABLE jobs;
TRUNCATE TABLE companies;
TRUNCATE TABLE students;
SET FOREIGN_KEY_CHECKS=1;

-- Seed admin (admin / admin123) if not present
SELECT 'admin', '$2b$10$GWXnVcBgxiUmsZDWF1zGTejzj8TtiwzGBYp.xLwpjwKMl/v.2/QLy', 'Placement Admin'
WHERE NOT EXISTS (SELECT 1 FROM admins WHERE username = 'admin');

